// Language setup: which languages exist, which one to start with, and remembering the choice.
// The rest of src/i18n is generated by typesafe-i18n (`pnpm i18n`), except formatters.ts and the
// translation folders (en/, es/, fr/).

import {
  localStorageDetector,
  navigatorDetector,
} from "typesafe-i18n/detectors";
import type { Locales } from "./i18n-types.js";
import { detectLocale, locales } from "./i18n-util.js";
import { loadAllLocales } from "./i18n-util.sync.js";

/** Where the chosen language is saved in this browser. */
const LANGUAGE_STORAGE_KEY = "lang";

/** How each language names itself in the picker, and whether it is a draft translation. */
export const LANGUAGE_INFO: Record<Locales, { nativeName: string; isDraft: boolean }> = {
  en: { nativeName: "English", isDraft: false },
  es: { nativeName: "Español", isDraft: true },
  fr: { nativeName: "Français", isDraft: true },
};

/** Every supported language code, in picker order. */
export const SUPPORTED_LANGUAGES: readonly Locales[] = locales;

// All translations are small, so load every language up front (no network round trip later).
loadAllLocales();

/** The language to start in: a saved choice, else the browser's language, else English. */
export function detectInitialLanguage(): Locales {
  return detectLocale(localStorageDetector, navigatorDetector);
}

/** Saves the choice for next time and tells the browser (and screen readers) the page language. */
export function rememberLanguage(language: Locales): void {
  try {
    window.localStorage.setItem(LANGUAGE_STORAGE_KEY, language);
  } catch {
    // Private windows can block storage; the choice then lasts only for this visit.
  }
  document.documentElement.lang = language;
}
